:root {
  /* Colors */
  --color-fog-canvas: #fafafa;
  --color-paper: #ffffff;
  --color-pebble-tile: #ededed;
  --color-frosted-glass: #ffffff8f;
  --color-carbon-ink: #1c1a17;
  --color-slate-label: #52525b;
  --color-graphite-ink: #1c1a17b8;
  --color-ash-caption: #1c1a178f;
  --color-mist-border: #f4f4f5;
  --color-pewter-hairline: #0000001f;
  --color-ember-signal: #ff6020;
  --color-mint-pulse: #10b981;
  --color-amethyst-highlight: #a855f7;

  /* Typography — Font Families */
  --font-mona-sans: "Mona Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.2;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.33;
  --tracking-caption: 0.48px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: -0.14px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: -0.16px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.33;
  --tracking-body-lg: -0.18px;
  --text-subheading: 24px;
  --leading-subheading: 1.2;
  --tracking-subheading: -0.72px;
  --text-heading-sm: 32px;
  --leading-heading-sm: 1.125;
  --tracking-heading-sm: 0px;
  --text-heading: 40px;
  --leading-heading: 1.2;
  --tracking-heading: -0.4px;
  --text-display: 56px;
  --leading-display: 1;
  --tracking-display: -0.56px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-88: 88px;
  --spacing-120: 120px;

  /* Layout */
  --layout-page-max-width: 1080px;
  --layout-frame-width: 1128px;
  --layout-section-gap: 88px;
  --layout-card-padding: 24px;
  --layout-element-gap: 8px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-lg-2: 10px;
  --radius-xl: 12px;
  --radius-2xl: 20px;
  --radius-3xl: 24px;
  --radius-3xl-2: 48px;
  --radius-full: 999px;

  /* Named Radii */
  --radius-small-elements: 4px;
  --radius-badges: 6px;
  --radius-images: 8px;
  --radius-small-cards: 8px;
  --radius-inner-tiles: 10px;
  --radius-cards: 12px;
  --radius-tags: 20px;
  --radius-sections: 24px;
  --radius-buttons: 48px;
  --radius-pills: 999px;
  --radius-avatars: 50%;

  /* Shadows */
  --shadow-subtle: rgba(95, 99, 106, 0.08) 0px 0px 0px 1px, rgba(43, 43, 48, 0.1) 0px 1px 1px 0px;
  --shadow-subtle-2: rgba(95, 99, 106, 0.08) 0px 0px 0px 0.75px, rgba(43, 43, 48, 0.1) 0px 0.75px 0.75px 0px;
  --shadow-sm: rgba(17, 26, 37, 0.12) 0px 0px 0px 0.57px, rgba(16, 25, 36, 0.1) 0px 0.46px 1.14px 0px, rgba(16, 25, 36, 0.1) 0px 1.14px 4.57px 0px;
  --shadow-md: rgba(95, 99, 106, 0.12) 0px 0px 0px 1px, rgba(43, 43, 48, 0.1) 0px 1px 4px 0px;

  /* Surfaces */
  --surface-pebble-tile: #ededed;
  --surface-fog-canvas: #fafafa;
  --surface-paper: #ffffff;
  --surface-frosted-glass: #ffffff8f;
  --surface-carbon-ink: #1c1a17;
}

